const items = $input.all();
// GS gagal
if (!items || items.length === 0 || (items.length === 1 && items[0].json && items[0].json.error)) {
  const errMsg = (items[0] && items[0].json && items[0].json.error)
    ? (items[0].json.error.message || 'Database error')
    : 'Tidak ada data';
  return [{ json: { success: false, error: 'Gagal membaca data pekerja: ' + errMsg, data: [] } }];
}
const rows = items.map(i => i.json).filter(r => r.Nama || r.nama);
return [{ json: {
  success: true,
  count: rows.length,
  data: rows.map(r => ({
    nama: (String(r.Nama || r.nama || '')).trim(),
    no_hp: String(String(r.No_HP || r.no_hp || '')).trim()
  })).filter(r => r.nama)
}}];

const body      = $input.first().json.body || $input.first().json;
const nama      = (body.nama      || '').toString().trim();
const no_hp     = (body.no_hp     || '').toString().trim();
const keterangan= (body.keterangan|| '').toString().trim();
if (!nama) return [{ json: { valid: 'no', error: 'Nama pekerja tidak boleh kosong' } }];
const ts = new Date().toISOString();
return [{ json: { valid: 'yes', Nama: nama, No_HP: no_hp, Keterangan: keterangan, Timestamp: ts } }];

const item = $input.first().json;
if (item.error) {
  return [{ json: {
    success: false,
    error: 'Gagal menyimpan pekerja ke database: ' + (item.error.message || 'Unknown error')
  }}];
}
return [{ json: { success: true, message: 'Pekerja berhasil ditambahkan' } }];

const raw = $input.first().json;
const body = raw.body || raw;
const { project, pekerja, tanggal, catatan, items, total } = body;

// Validasi required fields
if (!project || !project.toString().trim()) {
  return [{ json: { valid: 'no', error: 'Proyek tidak boleh kosong' } }];
}
if (!pekerja || !pekerja.toString().trim()) {
  return [{ json: { valid: 'no', error: 'Nama pekerja tidak boleh kosong' } }];
}
if (!tanggal) {
  return [{ json: { valid: 'no', error: 'Tanggal tidak boleh kosong' } }];
}
if (!items || !Array.isArray(items) || items.length === 0) {
  return [{ json: { valid: 'no', error: 'Minimal 1 item pekerjaan harus diisi' } }];
}

// Validasi setiap item
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  if (!it.pekerjaan || !it.pekerjaan.toString().trim()) {
    return [{ json: { valid: 'no', error: `Item ${i+1}: nama pekerjaan tidak boleh kosong` } }];
  }
  if (it.vol === undefined || it.vol === null || it.vol === '' || isNaN(Number(it.vol)) || Number(it.vol) <= 0) {
    return [{ json: { valid: 'no', error: `Item ${i+1} (${it.pekerjaan}): volume harus lebih dari 0` } }];
  }
  if (!it.sat || !it.sat.toString().trim()) {
    return [{ json: { valid: 'no', error: `Item ${i+1} (${it.pekerjaan}): satuan tidak boleh kosong` } }];
  }
}

// Generate Batch_ID
const ts = new Date();
const pad = (n, l=2) => String(n).padStart(l, '0');
const batchId = 'PKJ-' + ts.getFullYear()
  + pad(ts.getMonth()+1) + pad(ts.getDate())
  + pad(ts.getHours()) + pad(ts.getMinutes()) + pad(ts.getSeconds());
const timestamp = ts.toISOString();

// Expand jadi satu item per pekerjaan
return items.map((it, idx) => ({
  json: {
    valid: 'yes',
    Batch_ID: batchId,
    Tanggal: tanggal,
    Proyek: String(project).trim(),
    Pekerja: String(pekerja).trim(),
    Catatan: catatan || '',
    No_Item: it.no || (idx + 1),
    Pekerjaan: String(it.pekerjaan).trim(),
    Vol: Number(it.vol),
    Sat: String(it.sat).trim(),
    Harga_Satuan: (it.harga_satuan !== undefined && it.harga_satuan !== null && it.harga_satuan !== '') ? Number(it.harga_satuan) : '',
    Total_Item: (it.total !== undefined && it.total !== null && it.total !== '') ? Number(it.total) : '',
    Total_Keseluruhan: (idx === 0 && total !== undefined && total !== null && total !== '') ? Number(total) : '',
    Timestamp_Submit: timestamp
  }
}));

const allItems = $input.all();

// Periksa error dari GS Append
const errored = allItems.filter(i => i.json && i.json.error);
const succeeded = allItems.filter(i => !i.json || !i.json.error);

if (errored.length > 0 && succeeded.length === 0) {
  // Semua gagal
  const errMsg = errored[0].json.error ? (errored[0].json.error.message || 'Database write error') : 'Unknown GS error';
  return [{ json: {
    gsOk: 'no',
    error: 'Gagal menyimpan semua item ke database: ' + errMsg,
    savedCount: 0,
    totalCount: allItems.length
  }}];
}

if (errored.length > 0) {
  // Sebagian gagal — tetap lanjut tapi beri warning
  console.log(`Warning: ${errored.length} dari ${allItems.length} item gagal tersimpan`);
}

// Ambil info dari item pertama yang berhasil (untuk WA dan response)
const first = succeeded[0] ? succeeded[0].json : allItems[0].json;
return [{ json: {
  gsOk: 'yes',
  Batch_ID: first.Batch_ID,
  Proyek: first.Proyek,
  Pekerja: first.Pekerja,
  Tanggal: first.Tanggal,
  Catatan: first.Catatan,
  savedCount: succeeded.length,
  totalCount: allItems.length,
  partialFail: errored.length > 0
}}];

const meta = $('Code - Aggregate GS Result').first().json;
const { Batch_ID, Proyek, Pekerja, Tanggal, Catatan, savedCount } = meta;
const raw  = $('Webhook - Submit Pekerjaan').first().json;
const body = raw.body || raw;
const { items } = body;

const workers    = $input.all().map(i => i.json);
const workerData = workers.find(w => (String(w.Nama || w.nama || '')).trim() === Pekerja);
const rawPhone   = workerData ? (workerData.No_HP || workerData.no_hp || '').toString().trim() : '';
const phone      = rawPhone.replace(/\D/g,'').replace(/^0+/,'62');

let msg = '*Pekerjaan Baru*\n\n';
msg += 'Halo *' + Pekerja + '*!\n';
msg += 'Ada pekerjaan baru:\n\n';
msg += '*Proyek:* ' + Proyek + '\n';
msg += '*Tanggal:* ' + Tanggal + '\n';
if (Catatan) msg += '*Catatan:* ' + Catatan + '\n';
msg += '\n*Daftar Pekerjaan:*\n';
(items || []).forEach((it, i) => {
  const noItem = it.no || (i + 1);
  msg += noItem + '. ' + it.pekerjaan + ' — ' + it.vol + ' ' + it.sat + '\n';
});
msg += '\nRef: ' + Batch_ID;
msg += '\n_TIM Interior_';

return [{ json: { phone, waMessage: msg, hasPhone: phone ? 'yes' : 'no', Batch_ID, Pekerja, savedCount } }];

const waItem = $input.first().json;
const meta = $('Code - Phone dan WA Message').first().json;
const { Batch_ID, savedCount, totalCount } = meta;

let waOk = false;
let waNote = '';

if (waItem.error) {
  // HTTP node sendiri gagal (network error, timeout, dll)
  waNote = 'Notifikasi WA gagal dikirim: ' + (waItem.error.message || 'HTTP error');
} else {
  // Cek respons kirimi.id (bisa bermacam format)
  const respCode = waItem.code || waItem.status_code;
  const respStatus = (waItem.status || '').toString().toLowerCase();
  const respMsg = (waItem.message || '').toString().toLowerCase();
  waOk = respCode === 200 || respStatus === 'success' || respMsg.includes('success') || respMsg.includes('sent');
  if (!waOk) {
    waNote = 'WA mungkin tidak terkirim. Respons: ' + JSON.stringify(waItem).substring(0, 100);
  }
}

const baseMsg = savedCount === totalCount
  ? `Pekerjaan tersimpan (${savedCount} item)`
  : `Pekerjaan tersimpan sebagian (${savedCount} dari ${totalCount} item)`;

return [{ json: {
  success: true,
  message: waOk ? baseMsg + ' & notifikasi WA terkirim' : baseMsg + (waNote ? ' — ' + waNote : ''),
  batch_id: Batch_ID,
  wa_sent: waOk,
  saved_items: savedCount,
  total_items: totalCount
}}];

const raw = $input.first().json;
const qs = raw.query || raw;
const pekerja = (qs.pekerja || '').toString().trim();
const project = (qs.project || '').toString().trim();
if (!pekerja && !project) {
  return [{ json: { valid: 'no', error: 'Isi minimal satu filter: pekerja atau project' } }];
}
return [{ json: { valid: 'yes', pekerja, project } }];

// $input = rows from GS - Baca Status Pekerjaan (may be empty if no statuses yet)
// pekerjaan rows come from GS - Baca Semua Pekerjaan via node reference

const pekerjaanItems = $('GS - Baca Semua Pekerjaan').all();
const statusItems    = $input.all();   // GS Status rows (may be empty — that's OK)

if (!pekerjaanItems || pekerjaanItems.length === 0) {
  return [{ json: { success: true, count: 0, data: [] } }];
}

// Validated filter params
const validated     = $('Code - Validate Get Pekerjaan').first().json;
const filterPekerja = (validated.pekerja || '').toString().trim();
const filterProyek  = (validated.project  || '').toString().trim();

// Build latest status map
const latestStatus = {};
statusItems.map(i => i.json)
  .filter(r => r && r.Batch_ID && r.No_Item && r.Status)
  .forEach(r => { latestStatus[r.Batch_ID + '|' + r.No_Item] = r.Status; });

// Pekerjaan rows
const rows = pekerjaanItems.map(i => i.json)
  .filter(r => r.Pekerjaan && r.Pekerjaan.toString().trim());

// Apply filters
const filtered = rows.filter(r => {
  const rPekerja = (r.Pekerja || '').toString().trim();
  const rProyek  = (r.Proyek  || '').toString().trim();
  if (filterPekerja && rPekerja !== filterPekerja) return false;
  if (filterProyek  && rProyek  !== filterProyek)  return false;
  return true;
});

// Group by Batch_ID
const groups = {};
filtered.forEach(r => {
  const bid = (String(r.Batch_ID || '')).trim();
  if (!bid) return;
  if (!groups[bid]) {
    groups[bid] = {
      id:      bid,
      project: (String(r.Proyek  || '')).trim(),
      pekerja: (String(r.Pekerja || '')).trim(),
      tanggal: (String(r.Tanggal || '')).trim(),
      catatan: (String(r.Catatan || '')).trim(),
      items:   [],
      total:   0
    };
  }
  const noItem = parseInt(r.No_Item) || groups[bid].items.length + 1;
  groups[bid].items.push({
    no:           noItem,
    pekerjaan:    (String(r.Pekerjaan    || '')).trim(),
    vol:          parseFloat(r.Vol) || 0,
    sat:          (String(r.Sat          || '')).trim(),
    harga_satuan: parseFloat(r.Harga_Satuan) || 0,
    total:        parseFloat(r.Total_Item)   || 0,
    status:       latestStatus[bid + '|' + noItem] || 'pending'
  });
  if (r.Total_Keseluruhan && !groups[bid].total)
    groups[bid].total = parseFloat(r.Total_Keseluruhan) || 0;
});

Object.values(groups).forEach(g => {
  if (!g.total) g.total = g.items.reduce((s,it) => s + (it.total||0), 0);
});

const data = Object.values(groups).sort((a,b) => new Date(b.tanggal)-new Date(a.tanggal));
return [{ json: { success: true, count: data.length, data } }];

const body = $input.first().json.body || $input.first().json;
const updates = body.updates;
if (!updates || !Array.isArray(updates) || updates.length === 0) {
  return [{ json: { valid: 'no', error: 'Array updates tidak boleh kosong' } }];
}
const validStatuses = ['pending', 'inprogress', 'done'];
for (const u of updates) {
  if (!u.batch_id || !u.batch_id.toString().trim())
    return [{ json: { valid: 'no', error: 'batch_id wajib ada di setiap update' } }];
  if (u.no_item === undefined || u.no_item === null || isNaN(parseInt(u.no_item)))
    return [{ json: { valid: 'no', error: 'no_item (nomor baris) wajib ada di setiap update' } }];
  if (!validStatuses.includes(u.status))
    return [{ json: { valid: 'no', error: `Status tidak valid: "${u.status}". Gunakan: pending | inprogress | done` } }];
}
const ts = new Date().toISOString();
return updates.map(u => ({
  json: {
    valid: 'yes',
    Batch_ID:   u.batch_id.toString().trim(),
    No_Item:    parseInt(u.no_item),
    Status:     u.status,
    Updated_At: ts
  }
}));

const allItems = $input.all();
const errs = allItems.filter(i => i.json && i.json.error);
const ok   = allItems.filter(i => !i.json || !i.json.error);
if (errs.length > 0 && ok.length === 0) {
  return [{ json: { success: false, error: 'Gagal menyimpan status: ' + (errs[0].json.error.message || 'DB error'), saved: 0 } }];
}
return [{ json: { success: true, message: `Status ${ok.length} item diperbarui`, saved: ok.length, failed: errs.length } }];

const rows = $input.all().map(i => i.json)
  .filter(r => r.Komplain || r.komplain);
const qs   = ($('Webhook - Get Komplain').first().json.query || {});
const filterProject = (qs.project || '').toString().trim();

const filtered = rows.filter(r => {
  if (!filterProject) return true;
  const proj = (r.Proyek || r.Nama_Project || '').toString().trim();
  return proj === filterProject;
});

const data = filtered.map(r => ({
  id:        (r.ID        || '').toString().trim(),
  _type:     'komplain',
  project:   (String(r.Proyek   || r.Nama_Project || '')).trim(),
  pengaju:   (String(r.Pengaju  || '')).trim(),
  tanggal:   (String(r.Tanggal  || r.Tanggal_Submit || r.Tanggal_Komplain || '')).trim(),
  komplain:  (String(r.Komplain || '')).trim(),
  status:    (String(r.Status   || 'open')).trim().toLowerCase(),
  prioritas: (String(r.Prioritas|| '')).trim(),
  lokasi:    (String(r.Lokasi   || '')).trim(),
})).sort((a, b) => new Date(b.tanggal) - new Date(a.tanggal));

return [{ json: { success: true, count: data.length, data } }];

const rows = $input.all().map(i => i.json);
const projects = rows
  .map(r => (r.Project || r.project || Object.values(r)[0] || '').toString().trim())
  .filter(Boolean);
return projects.length > 0
  ? projects.map(p => ({ json: { name: p } }))
  : [{ json: { _empty: true } }];

const body    = $input.first().json.body || $input.first().json;
const project = (body.project || '').toString().trim();
if (!project) return [{ json: { valid: 'no', error: 'Nama project tidak boleh kosong' } }];
return [{ json: { valid: 'yes', Project: project } }];

const body     = $input.first().json.body || $input.first().json;
const project  = (String(body.project  || '')).trim();
const pekerja  = (String(body.pekerja  || '')).trim();
const komplain = (String(body.komplain || '')).trim();

if (!project)  return [{ json: { valid: 'no', error: 'Proyek wajib diisi' } }];
if (!komplain) return [{ json: { valid: 'no', error: 'Deskripsi komplain wajib diisi' } }];

const ts      = new Date();
const tsIso   = ts.toISOString();
const dateStr = (body.tanggal || tsIso.slice(0, 10));

// Generate ID komplain (format: CMP-YYYYMMDDHHMMSS)
const pad = (n) => String(n).padStart(2, '0');
const id  = 'CMP-' + ts.getFullYear()
  + pad(ts.getMonth() + 1) + pad(ts.getDate())
  + pad(ts.getHours()) + pad(ts.getMinutes()) + pad(ts.getSeconds());

return [{ json: {
  valid:     'yes',
  ID:        id,
  Tanggal:   dateStr,
  Proyek:    project,
  Pengaju:   pekerja || body.pengaju || '',
  Komplain:  komplain,
  Lokasi:    (String(body.lokasi    || '')).trim(),
  Prioritas: (String(body.prioritas || 'Normal')).trim(),
  Status:    'Open',
  Timestamp: tsIso
}}];

const validated = $('Code - Validate Komplain').first().json;
const { Proyek, Pengaju, Komplain, Lokasi, Prioritas, Tanggal } = validated;

const workers    = $input.all().map(i => i.json);
const workerData = workers.find(w => (String(w.Nama || w.nama || '')).trim() === Pengaju);
const rawPhone   = workerData ? String(String(workerData.No_HP || workerData.no_hp || '')).trim() : '';
const phone      = rawPhone.replace(/\D/g,'').replace(/^0+/,'62');

let msg = '*Komplain Baru*\n\n';
msg += 'Halo *' + Pengaju + '*!\n';
msg += 'Komplain sudah dicatat.\n\n';
msg += '*Proyek:* ' + Proyek + '\n';
msg += '*Tanggal:* ' + Tanggal + '\n';
msg += '*Komplain:* ' + Komplain + '\n';
if (Lokasi)    msg += '*Lokasi:* ' + Lokasi + '\n';
if (Prioritas) msg += '*Prioritas:* ' + Prioritas + '\n';
msg += '\nTolong segera ditindaklanjuti.';

return [{ json: { phone, waMessage: msg, hasPhone: phone.length > 8 } }];

const body = $input.first().json.body || $input.first().json;
const id = String(body.id || '').trim();
const raw = String(body.status || '').trim().toLowerCase();
const map = { pending:'open', open:'open', inprogress:'inprogress', proses:'inprogress', done:'closed', closed:'closed', selesai:'closed' };
const status = map[raw] || 'open';
if (!id) return [{ json: { valid: 'no', error: 'ID komplain wajib diisi' } }];
return [{ json: { valid: 'yes', ID: id, Status: status, Updated_At: new Date().toISOString() } }];

// $input = Pekerja sheet rows (from GS - Read Pekerja Reminder)
const pekerjaRows   = $input.all().map(i => i.json).filter(r => r.Nama || r.nama);
const pekerjaanRows = $('GS - Read Pekerjaan Reminder').all().map(i => i.json)
  .filter(r => r.Batch_ID && r.Pekerjaan);
const statusRows    = $('GS - Read Status Reminder').all().map(i => i.json)
  .filter(r => r.Batch_ID && r.No_Item && r.Status);

// Latest status per "Batch_ID|No_Item"
const latestStatus = {};
statusRows.forEach(r => {
  latestStatus[r.Batch_ID + '|' + r.No_Item] = r.Status;
});

// WIB time period
const wibHour = (new Date().getUTCHours() + 7) % 24;
const period  = wibHour < 12 ? 'Pagi' : wibHour < 17 ? 'Siang' : 'Malam';

// Build per-batch, per-item — skip done items
const batches = {};
pekerjaanRows.forEach(r => {
  const bid    = r.Batch_ID;
  const noItem = r.No_Item || 1;
  const status = latestStatus[bid + '|' + noItem] || 'pending';
  if (status === 'done') return;

  if (!batches[bid]) {
    batches[bid] = {
      batch_id: bid,
      project:  (String(r.Proyek  || '')).trim(),
      pekerja:  (String(r.Pekerja || '')).trim(),
      catatan:  (String(r.Catatan || '')).trim(),
      items:    []
    };
  }
  batches[bid].items.push({
    pekerjaan: r.Pekerjaan,
    vol:       r.Vol,
    sat:       r.Sat,
    status
  });
});

// Group non-empty batches by pekerja
const byPekerja = {};
Object.values(batches).forEach(b => {
  if (!b.pekerja || b.items.length === 0) return;
  if (!byPekerja[b.pekerja]) byPekerja[b.pekerja] = [];
  byPekerja[b.pekerja].push(b);
});

if (Object.keys(byPekerja).length === 0) return [];

// Build WA per pekerja
const result = [];
Object.entries(byPekerja).forEach(([nama, jobs]) => {
  const worker   = pekerjaRows.find(w => (String(w.Nama || w.nama || '')).trim() === nama);
  const rawPhone = worker ? (worker.No_HP || worker.no_hp || '').toString().trim() : '';
  const phone    = rawPhone.replace(/\D/g,'').replace(/^0+/,'62');
  if (!phone) return;

  let msg = `\u23F0 *Pengingat ${period} \u2014 TIM Interior*\n\n`;
  msg += `Halo *${nama}*! Item pekerjaan yang masih perlu diselesaikan:\n\n`;

  jobs.forEach(job => {
    msg += `\ud83d\udccb *${job.project}*`;
    if (job.catatan) msg += ` \u2014 ${job.catatan}`;
    msg += `\n`;
    job.items.slice(0, 6).forEach((it, i) => {
      const stIcon = it.status === 'inprogress' ? '\ud83d\udd28' : '\u23f3';
      msg += `  ${stIcon} ${it.pekerjaan} (${it.vol} ${it.sat})\n`;
    });
    if (job.items.length > 6) msg += `  ... +${job.items.length - 6} item lainnya\n`;
    msg += `\n`;
  });
  msg += `_Update via aplikasi TIM Interior_`;

  result.push({ json: { phone, waMessage: msg, pekerja: nama, totalItems: jobs.reduce((s,j)=>s+j.items.length,0) } });
});

return result;
